// Run economy and permanent card exchange. Collection counts include equipped copies.
S.points=Math.max(0,S.points||0);
S.discoveredCards=[...new Set([...(S.discoveredCards||[]),...C.filter(c=>(S.collection[c.id]||0)>0).map(c=>c.id)])];
let packNewIndexes=[],exchangeFilter='all';
const CARD_PRICE={common:40,rare:70,epic:120};
const DUST_VALUE={common:5,rare:15,epic:40};
const EXCHANGE_PRICE={common:30,rare:90,epic:240};
const POTIONS=[
{id:'heal',name:'癒しの薬',icon:'✚',price:25,desc:'最大HPの20%を回復（端数切り上げ）。探索中も使用可能。'},
{id:'strength',name:'剛力の薬',icon:'♜',price:35,desc:'この戦闘中、筋力+1。'},
{id:'agility',name:'鉄肌の薬',icon:'◇',price:35,desc:'この戦闘中、守護+1。'},
{id:'fire',name:'燃焼の投擲薬',icon:'♨',price:40,targeted:true,desc:'対象の敵に20ダメージ。筋力の影響を受けない。'},
{id:'blast',name:'爆発の投擲薬',icon:'✹',price:45,desc:'敵全体に15ダメージ。筋力の影響を受けない。'},
{id:'guard',name:'防護の薬',icon:'⬡',price:30,desc:'自身に10ブロック。守護の影響を受けない。'},
{id:'draw',name:'手繰の薬',icon:'⌘',price:30,desc:'3枚引く。手札の上限は10枚。'},
{id:'energy',name:'元気の薬',icon:'✧',price:40,desc:'エナジー+2。'},
{id:'poison',name:'毒フラスコ',icon:'☠',price:35,targeted:true,desc:'対象の敵に毒を5付与。'},
{id:'creation',name:'創造の薬',icon:'⚗',price:50,desc:'デッキにない潜在カードをランダムに1枚、手札に生成。コスト0。このターン終了時に除外。'}
];
function discoverCard(id){if(!S.discoveredCards.includes(id))S.discoveredCards.push(id)}
openPacks=function(n){if(S.run||!Number.isInteger(n)||n<1||n>S.packs)return;S.packs-=n;revealed=[];packNewIndexes=[];let pool=packPool();for(let j=0;j<n;j++)revealed.push(rand(pool.filter(c=>c.rarity!=='common')).id,...Array.from({length:2},()=>rand(pool.filter(c=>c.rarity===(Math.random()<.25?'rare':'common'))).id));revealed.forEach((id,i)=>{if(!S.discoveredCards.includes(id)){packNewIndexes.push(i);discoverCard(id)}S.collection[id]=(S.collection[id]||0)+1});render()};
const flipEconomyBase=flipCards;flipCards=function(ids,actions){if(page!=='packs'||ids!==revealed)return flipEconomyBase(ids,actions);return `<div class="cards reveal-list">${ids.map((id,i)=>`<div class="flip-shell ${C[id].rarity}" style="--delay:${Math.min(i*.3,2.4)}s"><div class="flip-inner"><div class="card-back">◇<small>ASHBOUND</small></div><div class="card-front">${card(id,'',packNewIndexes.includes(i)?'<b class="new-card-badge">新規</b>':'')}</div></div></div>`).join('')}</div>`};
function deleteDeckSet(i){if(S.run||!Number.isInteger(i)||i<0||i>=5)return;S.deckSets[i]=null;S.deckSetMeta[i]={name:'SET '+(i+1),relicId:null};render();toast(`マイセット ${i+1} を削除しました`)}
function excessCards(){return C.filter(c=>!c.retired&&!c.runOnly&&(S.collection[c.id]||0)>3).map(c=>({id:c.id,amount:S.collection[c.id]-3,points:(S.collection[c.id]-3)*DUST_VALUE[c.rarity]}))}
function convertExcess(){if(S.run)return;let list=excessCards(),points=list.reduce((n,c)=>n+c.points,0);if(!points)return;for(let c of list)S.collection[c.id]=3;S.points+=points;render();toast(`${list.reduce((n,c)=>n+c.amount,0)}枚を${points}ptに変換しました`)}
function exchangeCard(id){let c=C[id];if(S.run||!c||c.runOnly||c.retired||S.points<EXCHANGE_PRICE[c.rarity]||(S.collection[id]||0)>=3)return;S.points-=EXCHANGE_PRICE[c.rarity];S.collection[id]=(S.collection[id]||0)+1;discoverCard(id);render();toast(c.name+'を1枚取得しました')}
function exchangeHTML(){let list=excessCards(),n=list.reduce((n,c)=>n+c.amount,0),points=list.reduce((n,c)=>n+c.points,0),pool=packPool().filter(c=>exchangeFilter==='all'||c.rarity===exchangeFilter).sort((a,b)=>cardOrder(a.id,b.id));return `<div class="eyebrow">CARD EXCHANGE</div><h2>カード交換所</h2><p>デッキ内・未使用を合わせて各種類3枚を残し、余剰分だけをポイントに変換します。<br>マイセットと編成中のカードはそのまま使えます。</p><div class="exchange-balance"><strong>✧ ${S.points} pt</strong><button onclick="go('deck')">デッキへ戻る →</button></div><section class="tile exchange-convert"><h3>余剰カードを一括変換</h3><p>COMMON：5pt ／ RARE：15pt ／ EPIC：40pt（1枚あたり）</p><button class="primary" onclick="convertExcess()" ${n?'':'disabled'}>${n}枚を ${points}pt に変換</button>${n?`<details><summary>変換対象を確認</summary><ul>${list.map(x=>`<li>${C[x.id].name}：${x.amount}枚 → ${x.points}pt</li>`).join('')}</ul></details>`:'<p>4枚以上所持しているカードはありません。</p>'}</section><h3>基礎カードと交換</h3><p>COMMON：30pt ／ RARE：90pt ／ EPIC：240pt。1回につき1枚、所持3枚まで交換可能。</p><div class="toolbar">${['all','common','rare','epic'].map(k=>`<button class="${exchangeFilter===k?'primary':''}" onclick="exchangeFilter='${k}';render()">${k==='all'?'すべて':k.toUpperCase()}</button>`).join('')}</div><div class="economy-grid">${pool.map(c=>`<div class="merchandise">${card(c.id)}<span>所持 ${S.collection[c.id]||0} / 3枚</span><button onclick="exchangeCard(${c.id})" ${(S.collection[c.id]||0)>=3||S.points<EXCHANGE_PRICE[c.rarity]?'disabled':''}>${(S.collection[c.id]||0)>=3?'所持上限':EXCHANGE_PRICE[c.rarity]+'ptで交換'}</button></div>`).join('')}</div>`}
const homeEconomyBase=home;home=function(){return homeEconomyBase()+`<section class="tile exchange-home"><h3>余剰カードを、新しい力へ。</h3><p>所持ポイント ${S.points}pt。4枚目以降の基礎カードをまとめて変換できます。</p><button onclick="go('exchange')">カード交換所 →</button></section>`};
const deckEconomyBase=deck;deck=function(){let html=deckEconomyBase();return S.run?html:html.replace('<h2>デッキの編成</h2>',`<h2>デッキの編成</h2><div class="toolbar"><button onclick="go('exchange')">余剰カード変換・基礎カード交換　✧ ${S.points}pt</button></div>`)};
function runCopies(r,id){return r.deck.filter(x=>x===id).length}
function buildShop(r){let cards=[];for(let [rarity,n] of [['common',3],['rare',2],['epic',1]])cards.push(...shuffle(C.filter(c=>allowedRunCard(c,r)&&c.rarity===rarity)).slice(0,n).map(c=>({id:c.id,price:CARD_PRICE[rarity],sold:false})));return {floor:r.floor,cards,potions:shuffle([...POTIONS]).slice(0,3).map(p=>({id:p.id,price:p.price,sold:false}))}}
const chooseEconomyBase=choose;choose=function(type){let r=S.run;if(type==='shop'){r.kind='shop';r.shop=buildShop(r);r.mode=page='shop';render();return}if(type==='event'){r.kind='event';let eligible=C.filter(c=>allowedRunCard(c,r)&&c.rarity==='epic'&&runCopies(r,c.id)<3);r.chest={floor:r.floor,card:eligible.length?rand(eligible).id:null,gold:100,claimed:false};r.mode=page='chest';render();return}return chooseEconomyBase(type)};
function chestHTML(){let r=S.run,c=r.chest;return `<div class="reward"><div class="eyebrow">TREASURE CHEST</div><div class="chest-emblem">▣</div><h1>灰に眠る宝箱</h1><p>潜在EPICカード1枚と、100金が入っています。</p>${c.card!=null?flipCards([c.card]):'<p>すべてのEPICカードが3枚に達しているため、カードは取得できません。</p>'}<div class="chest-gold">◈ ${c.gold} 金</div><p>${c.claimed?'カードと金を受け取りました。':'カードは今回のランのデッキに追加されます。'}</p><button class="primary" onclick="claimChest()">${c.claimed?'探索を続ける →':'中身を受け取って進む →'}</button></div>`}
function claimChest(){let r=S.run;if(page!=='chest'||!r?.chest||busy)return;let c=r.chest;if(!c.claimed){r.gold+=c.gold;if(c.card!=null&&runCopies(r,c.card)<3)addRunCard(r,c.card);c.claimed=true}next()}
function shopHTML(){let r=S.run,s=r.shop;return `<div class="eyebrow">ASH MARKET</div><h2>灰商人のショップ</h2><div class="exchange-balance"><strong>◈ ${r.gold}</strong><button class="primary" onclick="next()">探索を続ける →</button></div><p>今回のランで得た金を使用します。商品は各1点限り。カードとポーションは今回のランのみ有効です。</p><h3>潜在カード</h3><div class="economy-grid">${s.cards.map((x,i)=>`<div class="merchandise ${x.sold?'sold':''}">${card(x.id)}<span>ラン内 ${runCopies(r,x.id)} / 3枚</span><button onclick="buyShopCard(${i})" ${x.sold||r.gold<x.price||runCopies(r,x.id)>=3?'disabled':''}>${x.sold?'売り切れ':runCopies(r,x.id)>=3?'所持上限':'◈ '+x.price+' 金で購入'}</button></div>`).join('')}</div><h3>消費アイテム <small>所持 ${r.potions?.length||0} / 2</small></h3><div class="potion-shop">${s.potions.map((x,i)=>{let p=POTIONS.find(p=>p.id===x.id);return `<article class="tile"><div class="potion-icon">${p.icon}</div><h3>${p.name}</h3><p>${p.desc}</p><button onclick="buyShopPotion(${i})" ${x.sold||r.gold<x.price||(r.potions?.length||0)>=2?'disabled':''}>${x.sold?'売り切れ':(r.potions?.length||0)>=2?'所持上限（2個）':'◈ '+x.price+' 金で購入'}</button></article>`}).join('')}</div>`}
function buyShopCard(i){let r=S.run,x=r?.shop?.cards[i];if(page!=='shop'||busy||!x||x.sold||r.gold<x.price||runCopies(r,x.id)>=3)return;r.gold-=x.price;addRunCard(r,x.id);x.sold=true;render()}
function buyShopPotion(i){let r=S.run,x=r?.shop?.potions[i];if(page!=='shop'||busy||!x||x.sold||r.gold<x.price||(r.potions?.length||0)>=2)return;r.gold-=x.price;(r.potions??=[]).push(x.id);x.sold=true;render()}
function canUsePotion(p,allowTarget=false){let r=S.run;return !!(p&&r&&!(p.id==='energy'&&r.energyLocked)&&!busy&&!r.pendingChoice&&!r.hunterChoice&&!r.pendingDiscard&&(allowTarget||r.potionTarget==null)&&page===r.mode&&['map','battle','shop','chest','rest','mystery','reward','event'].includes(page)&&(p.id==='heal'?r.hp<r.max:page==='battle')&&(!['draw','creation'].includes(p.id)||(r.hand||[]).length<10))}
function creationCandidates(r){return C.filter(c=>allowedRunCard(c,r)&&!r.deck.includes(c.id))}
async function usePotion(i){let r=S.run,p=POTIONS.find(p=>p.id===r?.potions?.[i]);if(!canUsePotion(p))return;if(p.targeted){r.potionTarget=i;clearDrag();render();return}return resolvePotion(i,null)}
function cancelPotionTarget(){if(!S.run||busy)return;S.run.potionTarget=null;render()}
async function targetPotion(enemyIndex){let r=S.run;if(r?.potionTarget==null)return;return resolvePotion(r.potionTarget,enemyIndex)}
async function resolvePotion(i,enemyIndex){let r=S.run,p=POTIONS.find(p=>p.id===r?.potions?.[i]);if(!canUsePotion(p,true))return;if(p.targeted&&(r.potionTarget!==i||!r.enemies[enemyIndex]||r.enemies[enemyIndex].hp<=0))return;if(p.id==='creation'&&!creationCandidates(r).length)return toast('デッキにない潜在カードがありません');let old=r.enemies?.map(e=>e.hp)||[];r.potions.splice(i,1);r.potionTarget=null;
if(p.id==='heal')healHP(r,Math.ceil(r.max*.2));
else if(p.id==='strength')r.str++;
else if(p.id==='agility')r.agility=(r.agility||0)+1;
else if(p.id==='fire')damage(r.enemies[enemyIndex],20);
else if(p.id==='blast')r.enemies.filter(e=>e.hp>0).forEach(e=>damage(e,15));
else if(p.id==='guard')gainBlock(r,10,'potion');
else if(p.id==='draw')draw(3);
else if(p.id==='energy')gainEnergy(r,2);
else if(p.id==='poison')addPoison(r.enemies[enemyIndex],5+(typeof hasRelic==='function'&&hasRelic('poison_boost',r)?1:0));
else if(p.id==='creation'){let source=rand(creationCandidates(r)),id=nextBattleCardId(r);let entry={id,origin:source.id,createdTurn:r.turn};(r.generatedCards??=[]).push(entry);hydrateGeneratedCard(entry);r.hand.push(id)}
if(page==='battle'&&['fire','blast'].includes(p.id)){busy=true;save();try{for(let j=0;j<r.enemies.length;j++){let lost=old[j]-r.enemies[j].hp;if(lost>0)await animateEntity(j,'hit',lost);if(old[j]>0&&r.enemies[j].hp<=0)await animateEntity(j,'death')}}finally{busy=false}if(r.enemies.every(e=>e.hp<=0)){victory();return}if(r.kind==='boss')bossPlan(r)}render();toast(p.name+'を使用しました')}
function potionBelt(){let r=S.run;if(!r)return '';return `<section class="potion-belt" aria-label="消費アイテム"><b>消費アイテム ${r.potions?.length||0} / 2</b>${(r.potions||[]).map((id,i)=>{let p=POTIONS.find(p=>p.id===id);return `<span class="potion-slot"><button onclick="usePotion(${i})" ${canUsePotion(p)?'':'disabled'} aria-label="${p.name}を使用">${p.icon} ${p.name}</button><aside class="tooltip"><strong>${p.name}</strong><p>${p.desc}</p><p>使うとなくなります。</p></aside></span>`}).join('')}${Array.from({length:Math.max(0,2-(r.potions?.length||0))},()=>'<span class="potion-empty">空き</span>').join('')}${r.potionTarget!=null?`<strong class="potion-target-label">対象の敵を選択</strong><button onclick="cancelPotionTarget()">キャンセル</button>`:''}</section>`}
function wirePotionTargets(){let r=S.run;if(page!=='battle'||r?.potionTarget==null)return;document.querySelectorAll('[data-entity]').forEach(el=>{let key=el.dataset.entity;if(key==='player'||r.enemies[+key]?.hp<=0)return;el.classList.add('potion-target');el.setAttribute('role','button');el.setAttribute('tabindex','0');el.setAttribute('aria-label',r.enemies[+key].name+'にアイテムを使用');el.onclick=()=>targetPotion(+key);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();targetPotion(+key)}}})}
const renderEconomyBase=render;render=function(){if(globalThis.ASHBOUND_LOADING)return;renderEconomyBase();if(page==='shop'&&S.run)$('app').innerHTML=shopHTML();else if(page==='chest'&&S.run)$('app').innerHTML=chestHTML();else if(page==='exchange')$('app').innerHTML=exchangeHTML();if(S.run&&page===S.run.mode)$('app').insertAdjacentHTML('afterbegin',potionBelt());wirePotionTargets();save()};
const goEconomyBase=go;go=function(p){if(p==='exchange'&&S.run)return toast('カード交換所は拠点で利用できます');if(S.run)S.run.potionTarget=null;goEconomyBase(p)};
// Preserve current encounters. Add shop choices only to unvisited ordinary nodes.
if(S.run&&!S.run.economyVersion){let r=S.run;for(let row of r.nodes||[])for(let n of row)if(n.row>=r.floor-1&&n.row>0&&n.row<8&&n.type==='fight'&&Math.random()<.18)n.type='shop';r.economyVersion=1}
const createMapEconomyBase=createMap;createMap=function(r){createMapEconomyBase(r);r.economyVersion=1};
// Existing inventory: preserve the first two and refund old purchase prices for overflow.
if(S.run&&!S.run.potionCapacityVersion){let r=S.run,overflow=(r.potions||[]).slice(2);r.potions=(r.potions||[]).slice(0,2);r.gold+=overflow.reduce((n,id)=>n+({heal:25,guard:30,energy:40}[id]||POTIONS.find(p=>p.id===id)?.price||0),0);r.potionCapacityVersion=1}

